    "summary": "Wire, cable, rope, and strand dynamics simulation"
  },
  "rag_material_binding_strength": {
    "description": "Material binding strength override in Solaris. Covers Assign Material LOP bindingstrength parameter, weakerThanDescendants vs strongerThanDescendants, when materials don't apply due to existing bindings, Unassign Material for clearing bindings.",
    "keywords": ["material binding", "binding strength", "material override", "material not working", "material not applying", "default material", "stronger than descendants", "weaker than descendants", "unassign material", "clear material"],
    "reference_file": "rag_material_binding_strength",
    "summary": "Material binding strength and override patterns in Solaris LOPs"
  },
  "rag_material_library_setup": {
    "description": "Creating materials inside Material Library LOP. CRITICAL: matlib.cook(force=True) BEFORE createNode() on shader children. Multiple material subnets, geopath assignment directly in matlib, wiring order.",
    "keywords": ["material library", "matlib", "create material", "material subnet", "matlib cook", "multiple materials", "material scope", "matlib setup", "geopath"],
    "reference_file": "rag_material_library_setup",
    "summary": "Material Library LOP creation, cooking requirement, and multi-material setup"
  },
  "rag_material_vexpression": {
    "description": "Dynamic material assignment using VEXpressions in LOPs. CRITICAL: LOPs use @elemnum not @ptnum. Conditional material assignment, attribute-driven assignment via primvars.",
    "keywords": ["vexpression material", "dynamic material", "conditional material", "elemnum", "ptnum", "attribute driven material", "material per prim", "lop vexpression"],
    "reference_file": "rag_material_vexpression",
    "summary": "VEXpression-based dynamic material assignment in LOPs (@elemnum, not @ptnum)"
  },
  "rag_material_mtlx_encoding": {
    "description": "MaterialX as USD prims workflow. How MaterialX nodes become USD shader prims, mtlx: namespace, reading/writing MaterialX parameters through USD API, Sdf.ValueTypeNames, the _shader suffix issue.",
    "keywords": ["materialx usd", "mtlx encoding", "materialx prim", "shader prim", "mtlx namespace", "materialx usd api", "material shader suffix", "sdf value types"],
    "reference_file": "rag_material_mtlx_encoding",
    "summary": "MaterialX shader encoding as USD prims with Sdf value types"
  },
  "rag_material_primvar_driven": {
    "description": "shop_materialpath and primvar-driven material assignment. SOP-level attribute propagation to LOPs, primvar readers in MaterialX, using geometry attributes to drive shader parameters.",
    "keywords": ["shop_materialpath", "primvar material", "attribute driven material", "geometry material", "sop material", "material attribute", "primvar reader"],
    "reference_file": "rag_material_primvar_driven",
    "summary": "SOP-to-LOP material assignment via shop_materialpath and primvar-driven shading"
  },
  "rag_material_karma_xpu": {
    "description": "Karma XPU material constraints. XPU supports MaterialX ONLY (no VEX shaders), checking renderer compatibility, XPU-unsupported features (custom AOVs, some SSS modes), fallback to CPU.",
    "keywords": ["karma xpu", "xpu material", "xpu limitation", "materialx only", "xpu shader", "xpu compatibility", "gpu render", "xpu vs cpu"],
    "reference_file": "rag_material_karma_xpu",
    "summary": "Karma XPU material constraints — MaterialX only, no VEX shaders"
  },
  "rag_material_path_expressions": {
    "description": "USD path expressions vs Houdini prim patterns for material assignment. Exact prim paths required for bindings, wildcard patterns for targeting, collection-based targeting.",
    "keywords": ["usd path expression", "prim pattern", "material path", "prim selection", "wildcard prim", "collection target", "exact prim path", "glob pattern lop"],
    "reference_file": "rag_material_path_expressions",
    "summary": "USD path expressions vs Houdini glob patterns — exact paths required for material bindings"
  },
  "rag_material_collect_vop": {
    "description": "Multi-renderer material switching. Collect VOP pattern for multi-output materials across Karma CPU, XPU, and other delegates. USD material purpose outputs.",
    "keywords": ["collect vop", "multi renderer", "material switching", "renderer specific", "karma cpu xpu material", "render delegate material", "universal material"],
    "reference_file": "rag_material_collect_vop",
    "summary": "Multi-renderer material switching with Collect VOP and USD material outputs"
  },
  "rag_material_texture_override": {
    "description": "Texture parameter overrides in Karma. Per-prim texture variation via Edit Properties LOP, UDIM setup, CPU vs XPU texture handling differences.",
    "keywords": ["texture override", "texture parameter", "per-prim texture", "edit properties material", "texture path", "instanced material", "udim", "texture streaming"],
    "reference_file": "rag_material_texture_override",
    "summary": "Texture overrides, UDIM setup, and CPU vs XPU texture handling"
  },
  "rag_material_common_errors": {
    "description": "Consolidated material error patterns. Grey/default shader (binding didn't take), material not visible (check binding strength), matlib cook error, wrong prim path, @ptnum vs @elemnum, scope mismatch.",
    "keywords": ["material error", "grey shader", "default material", "material not visible", "material debug", "material troubleshoot", "matlib error", "material assignment failed"],
    "reference_file": "rag_material_common_errors",
    "summary": "Material error diagnostics: grey shader, invisible material, matlib cook, path mismatch"
  },
  "rag_dop_wiring_order": {
    "description": "DOP node wiring conventions. DOPs use merge-based connections (NOT SOP-style direct wiring). Objects first, then forces, then solvers via merge nodes. enforceWiringOrder, findOrCreateMergeInput pattern.",
    "keywords": ["dop wiring", "dop merge", "dop connection", "enforceWiringOrder", "merge input", "dop node order", "dop network wiring", "connect dop nodes"],
    "reference_file": "rag_dop_wiring_order",
    "summary": "DOP merge-based wiring conventions: objects → forces → solver via merge"
  },
  "rag_dop_simulation_guard": {
    "description": "ALWAYS wrap DOP network creation/modification in simulation-enabled guard. hou.setSimulationEnabled(False) try/finally pattern prevents crashes and incorrect initial state.",
    "keywords": ["simulation guard", "setSimulationEnabled", "disable simulation", "simulation during edit", "dop crash", "safe dop editing", "simulation enabled"],
    "reference_file": "rag_dop_simulation_guard",
    "summary": "Simulation-enabled guard pattern for safe DOP network editing"
  },
  "rag_dop_solver_creation": {
    "description": "Creating solvers in DOP networks. Bullet RBD, Pyro, FLIP, Vellum solver setup. Substep guidelines, solver wiring from merge output, solver configuration.",
